  owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  "flow" text not null,
  "category" text not null,
  "title" text not null,
  "description" text,
  "price" double precision not null,
  "price_unit" text default 'each',
  "quantity" double precision default 1,
  "animal_id" uuid,
  "photos" jsonb,
  "details" jsonb,
  "lat" double precision,
  "lng" double precision,
  "village" text,
  "contact_phone" text,
  "status" text default 'active',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  server_updated_at timestamptz not null default now()
);
create index if not exists "listings_sync_idx" on public."listings" (owner_id, server_updated_at);
drop trigger if exists "listings_touch" on public."listings";
create trigger "listings_touch" before insert or update on public."listings"
  for each row execute function public.touch_server_updated_at();
alter table public."listings" enable row level security;
drop policy if exists "listings_owner_all" on public."listings";
create policy "listings_owner_all" on public."listings" for all to authenticated
  using (owner_id = auth.uid()) with check (owner_id = auth.uid());

